t.script:
(function () {
  /* ── Lookup tables (mirrors calculator.js) ── */
  var AUD = {
    idea_personal:    { urgency:.85, riskMult:1.20, mktCapture:.60, insight:'Every month of delay is money from your own pocket — and an open door for competitors to enter your market first.', rec:'Start with a lean MVP targeting your first 10–20 paying customers. Budget 4–6 months of focused development with a reliable technical partner.' },
    idea_funded:      { urgency:.95, riskMult:1.70, mktCapture:.75, insight:'Investor runway has a hard deadline. Slow execution compresses your window to hit milestones and close your next funding round.', rec:'Speed to a working product is everything. Investors expect milestones on schedule — a strong development partner can halve your time-to-demo.' },
    unsatisfied_team: { urgency:.90, riskMult:1.50, mktCapture:.65, insight:'An underperforming team doubles your cost — you pay salaries AND lose market time simultaneously.', rec:'Audit your current output vs monthly spend. Switching to the right partner typically saves 40–60% long-term and recovers 3–6 months of lost velocity.' },
    mvp_investment:   { urgency:.80, riskMult:1.40, mktCapture:.70, insight:'Your MVP proves the concept. Now you need execution speed and code quality to scale before competitors replicate your idea.', rec:'Prioritise scalability, code quality, and feature delivery speed. The right team pays for itself within 3–4 months.' },
    mvp_ai:           { urgency:.88, riskMult:1.60, mktCapture:.60, insight:'AI-generated code carries hidden technical debt — security vulnerabilities, no scalability plan, logic that breaks under real users.', rec:'Get a professional technical audit before scaling marketing or pitching investors. Fixing AI-built MVPs early costs 3x less than a full rebuild under pressure.' },
    non_technical:    { urgency:.75, riskMult:1.10, mktCapture:.50, insight:'Without technical knowledge, the wrong vendor can burn your entire budget with little to show — the most common founder mistake.', rec:'Start with a discovery and prototype phase before committing to full development. Validate cheaply with a trusted partner, then scale with confidence.' },
  };
  var ST = {
    b2b:         { competition:.60, timeToRev:3 },
    b2c:         { competition:.85, timeToRev:5 },
    marketplace: { competition:.78, timeToRev:7 },
    enterprise:  { competition:.50, timeToRev:9 },
  };

  var fmt  = function(n){ return '$' + Math.round(n).toLocaleString(); };
  var fmtK = function(n){ var v=Math.round(n); return v>=1000?'$'+(v/1000).toFixed(0)+'K':fmt(v); };
  var flt  = function(id){ return parseFloat(document.getElementById(id).value)||0; };

  function oppScore(ak, sk, budget, rev) {
    var a=AUD[ak], s=ST[sk];
    var fit = Math.min(budget/Math.max(rev*.40,1),1);
    var mkt = 1-s.competition;
    return Math.round(Math.min(99,Math.max(10,(fit*40)+(mkt*35)+(a.mktCapture*25))));
  }
  function monthlyLost(rev, ak, sk) {
    return Math.round((rev/12)*AUD[ak].urgency*ST[sk].competition);
  }
  function delayLoss(mo, months, mult) {
    var t=0; for(var i=0;i=80) return {text:'Strong Opportunity',    cls:'opp-strong'};
    if(sc>=60) return {text:'Good Opportunity',      cls:'opp-good'};
    if(sc>=40) return {text:'Moderate — Act Strategically', cls:'opp-moderate'};
    if(sc>=20) return {text:'Challenging — Plan Carefully', cls:'opp-challenging'};
    return           {text:'High Risk — Seek Guidance', cls:'opp-risky'};
  }
  function buildTime(sk, budget) {
    var base=ST[sk].timeToRev;
    var sp=budget>=80000?.65:budget>=40000?.80:budget>=20000?1.0:1.25;
    return Math.round(base*sp);
  }

  var trajChart=null;
  function drawTraj(data) {
    var ctx=document.getElementById('trajChart').getContext('2d');
    if(trajChart) trajChart.destroy();
    trajChart=new Chart(ctx,{type:'line',data:{labels:data.map(function(_,i){return i===0?'Now':i+'mo';}),datasets:[{data:data,borderColor:'#e53935',backgroundColor:'rgba(229,57,53,.08)',borderWidth:2,pointRadius:0,fill:true,tension:.4}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}},animation:{duration:800}}});
  }

  function validate() {
    var ok=true;
    var em=document.getElementById('fEmail').value.trim();
    var rv=flt('fRevenue'), bud=flt('fBudget');
    var show=function(id,v){var el=document.getElementById(id);if(v){el.classList.add('show');ok=false;}else el.classList.remove('show');};
    show('errEmail', !em || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em));
    show('errRevenue', rv<=0);
    show('errBudget', bud<=0);
    if(!em) document.getElementById('errEmail').textContent='Email is required';
    return ok;
  }

  document.getElementById('calcBtn').addEventListener('click', function(){
    if(!validate()) return;
    var ak=document.getElementById('fAudience').value;
    var sk=document.getElementById('fSaasType').value;
    var rev=flt('fRevenue'), budget=flt('fBudget');
    var a=AUD[ak], s=ST[sk];

    var sc   = oppScore(ak,sk,budget,rev);
    var mo   = monthlyLost(rev,ak,sk);
    var l6   = delayLoss(mo,6,a.riskMult);
    var l12  = delayLoss(mo,12,a.riskMult);
    var br   = budgetRange(rev);
    var roi  = Math.ceil(budget/(rev/12));
    var bt   = buildTime(sk,budget);
    var verd = verdict(sc);
    var traj = [];
    for(var i=0;i<=12;i++) traj.push(i===0?0:delayLoss(mo,i,a.riskMult));

    /* Badge */
    var badge=document.getElementById('oppBadge');
    badge.textContent=verd.text; badge.className='sc-opp-badge '+verd.cls;

    /* Score */
    document.getElementById('rScore').textContent=sc;
    document.getElementById('rVerdict').textContent=verd.text;
    var fill=document.getElementById('progFill');
    var col=sc>=80?'#1b5e20':sc>=60?'#1565c0':sc>=40?'#f57f17':'#c62828';
    fill.style.background=col; setTimeout(function(){fill.style.width=sc+'%';},50);

    /* Losses */
    document.getElementById('rMonthly').textContent=fmt(mo);
    document.getElementById('rLoss6').textContent=fmt(l6);
    document.getElementById('rLoss12').textContent=fmt(l12);

    /* Metrics */
    document.getElementById('rBudgetRange').textContent=fmtK(br.min)+' – '+fmtK(br.max);
    document.getElementById('rBuildTime').textContent=bt+' months';
    document.getElementById('rROI').textContent=roi+' months';

    /* Chart */
    drawTraj(traj);

    /* Insight */
    document.getElementById('rInsight').textContent=a.insight;

    /* Show results */
    document.getElementById('emptyState').style.display='none';
    document.getElementById('resContent').style.display='block';

    /* Store for modal */
    window._audit={ak:ak,sk:sk,rev:rev,budget:budget,sc:sc,mo:mo,l6:l6,l12:l12,br:br,roi:roi,bt:bt,verd:verd,a:a};

    /* Save to localStorage */
    try{var ls=JSON.parse(localStorage.getItem('saas_audit_leads')||'[]');ls.push({audienceType:ak,saasType:sk,revenueGoal:rev,budget:budget,timestamp:new Date().toISOString()});localStorage.setItem('saas_audit_leads',JSON.stringify(ls));}catch(_){}
  });

  /* Open modal */
  document.getElementById('openAuditBtn').addEventListener('click', function(){
    if(!window._audit) return;
    var d=window._audit;
    document.getElementById('modalSub').textContent='Opportunity Score '+d.sc+'/100 · '+d.verd.text+' · Revenue at Risk: '+fmt(d.mo)+'/month · 12-Month Loss if Delayed: '+fmt(d.l12);
    document.getElementById('rRecommendation').textContent=d.a.rec;
    document.getElementById('leadOk').style.display='none';
    document.getElementById('leadSubmit').style.display='block';
    document.getElementById('auditOverlay').classList.add('active');
  });

  /* Close modal */
  document.getElementById('closeModal').addEventListener('click', function(){ document.getElementById('auditOverlay').classList.remove('active'); });
  document.getElementById('auditOverlay').addEventListener('click', function(e){ if(e.target===document.getElementById('auditOverlay')) document.getElementById('auditOverlay').classList.remove('active'); });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') document.getElementById('auditOverlay').classList.remove('active'); });

  /* Lead submit */
  document.getElementById('leadSubmit').addEventListener('click', function(){
    var name=document.getElementById('lfName').value.trim();
    if(!name){alert('Please enter your name.');return;}
    var d=window._audit||{};
    var email=document.getElementById('fEmail').value.trim();
    var payload={
      name:name,
      phone:document.getElementById('lfPhone').value.trim(),
      company:document.getElementById('lfCompany').value.trim(),
      role:document.getElementById('lfRole').value.trim(),
      challenge:document.getElementById('lfChallenge').value.trim(),
      email:email,
      website:document.getElementById('fWebsite').value.trim(),
      audienceType:d.ak, saasType:d.sk,
      revenueGoal:d.rev, budget:d.budget,
      auditResults:{
        opportunityScore:d.sc, monthlyRevLost:d.mo,
        loss6Months:d.l6, loss12Months:d.l12,
        budgetMin:d.br?d.br.min:0, budgetMax:d.br?d.br.max:0,
        roiMonths:d.roi, buildTimeline:d.bt, verdict:d.verd?d.verd.text:'',
      },
      source:'saas_audit_calculator',
    };
    fetch('/saas-calculator/submit-lead',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).catch(function(){});
    try{var ls=JSON.parse(localStorage.getItem('saas_audit_leads_full')||'[]');ls.push(payload);localStorage.setItem('saas_audit_leads_full',JSON.stringify(ls));}catch(_){}
    document.getElementById('leadSubmit').style.display='none';
    document.getElementById('leadOk').style.display='block';
    var t=document.getElementById('toast');t.textContent='Thank you! We will be in touch within 24 hours.';t.classList.add('show');setTimeout(function(){t.classList.remove('show');},4000);
  });
})();
